// ═══ subList is a VIEW — writes go to parent ═══
List<String> accounts = new ArrayList<>(List.of("A", "B", "C", "D", "E"));
List<String> sub = accounts.subList(1, 4);  // [B, C, D] — indices 1,2,3
// sub is NOT a copy! It's a view into accounts.

sub.set(0, "B2");     // changes sub[0] = accounts[1]
// accounts = [A, B2, C, D, E]  ← parent CHANGED!

sub.remove(0);         // removes B2 from sub AND accounts
// sub = [C, D], accounts = [A, C, D, E]

sub.add("X");          // adds to sub AND accounts (at sub's range)
// sub = [C, D, X], accounts = [A, C, D, X, E]

// ═══ STRUCTURAL CHANGE TO PARENT → CME ═══
List<String> list = new ArrayList<>(List.of("A", "B", "C", "D"));
List<String> sub2 = list.subList(1, 3);  // [B, C]

list.add("E");  // STRUCTURAL change to parent!

// Next access to sub2 → ConcurrentModificationException!
// sub2.get(0);  → CME!
// sub2.size();  → CME!
// sub2 is INVALIDATED because parent's modCount changed.

// ═══ INDEPENDENT COPY — safe! ═══
List<String> original = new ArrayList<>(List.of("A", "B", "C", "D", "E"));
List<String> copy = new ArrayList<>(original.subList(1, 4));  // [B, C, D]
// copy is a SEPARATE list — not backed by original!

original.add("F");      // fine — doesn't affect copy
original.set(1, "B2");  // fine — doesn't affect copy
copy.add("X");           // fine — doesn't affect original

// ═══ subList for bulk operations ═══
List<String> data = new ArrayList<>(List.of("A", "B", "C", "D", "E", "F"));
data.subList(2, 5).clear();  // removes C, D, E from data!
// data = [A, B, F]  — efficient bulk delete!
