  class TradePaginator {
    private final List<Trade> trades;          // parent list
    // VIEW — backed by parent, write-through
    List<Trade> pageView(int off, int size) {
      return trades.subList(off, off + size);  // SubList(parent, off)
    }
    // SAFE copy — independent backing array
    List<Trade> pageCopy(int off, int size) {
      return new ArrayList<>(trades.subList(off, off + size));
    }
    void purgeRange(int from, int to) {
      trades.subList(from, to).clear();        // bulk remove O(range)
    }
  }
  // SubList fields: parent, offset, size, modCount
  // get(i) → parent.get(offset + i);  CME if parent.modCount changed
